insert into public.conocimiento (categoria, publico, titulo, etiquetas, contenido) values
-- Maderas
('madera', 'ambos', 'Cedro rojo', 'cedro madera semidura closet puertas aromática',
 'Madera semidura, aromática y estable, de color rojizo. Es fácil de trabajar y sus aceites naturales la hacen resistente a insectos, por eso es común en clósets, puertas y muebles finos. Su precio es medio-alto.'),
('madera', 'ambos', 'Caoba', 'caoba madera fina rojiza muebles finos',
 'Madera fina y estable, con veta rojiza que se oscurece con el tiempo. Se usa en muebles finos y puertas. Es costosa y es una especie regulada, por lo que conviene verificar que tenga procedencia legal.'),
('madera', 'ambos', 'Pino', 'pino madera blanda económica nudos',
 'Madera blanda, ligera y económica, con nudos visibles. Es fácil de trabajar pero se marca con golpes y es vulnerable al comején si no se trata. Buena para muebles económicos e interiores; requiere sellador y acabado.'),
('madera', 'ambos', 'Encino y roble', 'encino roble madera dura mesas sillas pisos',
 'Maderas duras, pesadas y muy resistentes, con veta marcada. Ideales para mesas, sillas y pisos que reciben mucho uso. Son más difíciles de trabajar y de costo alto.'),
('madera', 'ambos', 'Parota (guanacaste)', 'parota guanacaste mesa slab rústico',
 'Madera ligera con veta llamativa, muy usada en mesas de una sola pieza y muebles rústicos. Necesita un buen secado para evitar que se tuerza; su aserrín puede causar alergias al trabajarla.'),
('madera', 'ambos', 'Melina', 'melina madera plantación clara económica',
 'Madera de plantación, ligera, de color claro y económica. Se trabaja bien y sirve para muebles de interior y carpintería general; no es recomendable para exteriores.'),
('madera', 'ambos', 'Rosa morada', 'rosa morada madera semidura sureste',
 'Madera semidura del sureste de México, de color crema a café claro y buena trabajabilidad. Se usa en muebles y ebanistería.'),
('madera', 'ambos', 'Tzalam', 'tzalam madera yucatán dura puertas',
 'Madera tropical de la península de Yucatán, dura y resistente, de color café con vetas. Muy usada localmente en muebles, puertas y pisos.'),
('madera', 'ambos', 'Ciricote', 'ciricote madera fina yucateca decorativa',
 'Madera fina de la región, muy dura, con veta oscura muy decorativa. Se reserva para piezas especiales por su costo alto.'),
-- Tableros
('tablero', 'ambos', 'MDF', 'mdf fibra densidad media pintar lacar humedad',
 'Tablero de fibra de densidad media con superficie lisa, ideal para pintar o lacar. Se hincha con la humedad, por lo que en cocinas y baños conviene el MDF RH (resistente a la humedad, de color verde). Los tornillos sujetan poco en sus cantos. Espesores comunes: 3, 6, 9, 12, 15 y 18 mm.'),
('tablero', 'ambos', 'Melamina', 'melamina tablero closet cocina oficina tapacanto',
 'Tablero de aglomerado o MDF recubierto con papel melamínico: ya viene con acabado y no necesita pintura. Es la opción más usada en clósets, cocinas y muebles de oficina. Sus cantos se cubren con tapacanto y son sensibles a la humedad si quedan expuestos.'),
('tablero', 'ambos', 'Triplay (contrachapado)', 'triplay contrachapado capas fondos cajones marino',
 'Chapas de madera pegadas en capas cruzadas: es resistente, estable y sujeta bien los tornillos. Se usa en estructuras, fondos y cajones. El triplay marino resiste mejor la humedad.'),
('tablero', 'ambos', 'Aglomerado', 'aglomerado mdp partículas económico',
 'Tablero de partículas de madera prensadas. Es económico pero débil ante la humedad y con menor sujeción de tornillos. Es la base de muchas melaminas.'),
-- Acabados
('acabado', 'ambos', 'Barniz de poliuretano', 'barniz poliuretano mesa cubierta resistente mate brillante',
 'Forma una capa dura, resistente al desgaste y a la humedad; es el más recomendable para mesas y cubiertas. Existe en brillante, semimate y mate. Se aplica en capas delgadas lijando suavemente entre manos.'),
('acabado', 'ambos', 'Laca', 'laca nitrocelulosa acabado fino secado rápido',
 'Seca rápido y deja un acabado fino. Es menos resistente al calor y a la humedad que el poliuretano, por lo que se usa más en muebles de interior con poco uso rudo.'),
('acabado', 'ambos', 'Aceites y ceras', 'aceite linaza tung cera natural',
 'Acabado natural que resalta la veta y se siente como madera. Protege menos contra manchas y requiere mantenimiento periódico (reaplicar).'),
('acabado', 'ambos', 'Tinta para madera', 'tinta entintado color madera',
 'Da color a la madera antes del barniz. Siempre conviene probar el tono en un retazo de la misma madera, porque cada especie lo absorbe distinto.'),
('acabado', 'ambos', 'Sellador', 'sellador poro primera mano',
 'Primera capa que cierra el poro de la madera y la prepara para el acabado final. Mejora la adherencia y reduce el consumo de barniz.'),
('acabado', 'ambos', 'Acabados para exterior', 'exterior barniz marino filtro uv sol lluvia',
 'Para muebles expuestos al sol o la lluvia se recomienda barniz marino o con filtro UV y mantenimiento cada año.'),
-- Herrajes
('herraje', 'ambos', 'Bisagras de cazoleta', 'bisagra cazoleta cierre suave recta semicodo codo',
 'Estándar en clósets y cocinas, con cazoleta de 35 mm. Hay de cierre suave. Según cómo queda la puerta se usan rectas (puerta sobrepuesta), semicodo (dos puertas en un mismo costado) o codo (puerta embutida).'),
('herraje', 'ambos', 'Correderas para cajón', 'corredera cajón telescópica extensión total cierre suave',
 'Las telescópicas de extensión total permiten abrir el cajón completo; también existen con cierre suave. Se eligen según la profundidad del cajón y el peso que cargará.'),
('herraje', 'ambos', 'Jaladeras y sistema push', 'jaladera tirador push gola',
 'Las jaladeras definen mucho el estilo del mueble. Alternativas sin jaladera: perfil gola o sistema push (se abre al presionar la puerta).'),
('herraje', 'ambos', 'Sistemas corredizos para clóset', 'corredizo riel closet puertas corredizas',
 'Rieles superiores e inferiores para puertas corredizas; ahorran espacio frente al clóset. Requieren piso y techo nivelados para funcionar bien.'),
('herraje', 'ambos', 'Tapacanto', 'tapacanto canto pvc melamina pegamento',
 'Cinta de PVC o melamina que cubre los cantos de los tableros; protege de la humedad y da mejor acabado. Se aplica con pegamento termofusible o con enchapadora.'),
-- Herramientas
('herramienta', 'carpintero', 'Herramientas básicas para muebles de melamina', 'herramientas sierra taladro escuadra melamina',
 'Sierra de banco o circular con disco para melamina, taladro atornillador, broca de cazoleta de 35 mm, escuadra, flexómetro, prensas y enchapadora o plancha para tapacanto.'),
('herramienta', 'carpintero', 'Rebajadora (router)', 'rebajadora router fresas cantos ranuras',
 'Sirve para hacer ranuras, perfiles y cantos decorativos. Usa fresas adecuadas al material y trabaja en varias pasadas poco profundas.'),
('herramienta', 'carpintero', 'Ingletadora', 'ingletadora cortes ángulo molduras',
 'Hace cortes en ángulo precisos para marcos y molduras. Revisa la escuadra del disco antes de cortar piezas finales.'),
('herramienta', 'carpintero', 'Seguridad en el taller', 'seguridad lentes protector auditivo polvo cubrebocas',
 'Usa lentes, protección auditiva y cubrebocas contra polvo (sobre todo con MDF). Mantén guardas en sierras, desconecta herramientas al cambiar discos y trabaja con buena ventilación.'),
-- Cuidados (clima de Mérida)
('cuidado', 'ambos', 'Calor y humedad en Mérida', 'humedad calor mérida expansión aclimatar',
 'Con el calor y la humedad, la madera se expande y contrae. Conviene aclimatarla antes de trabajarla, sellar todas sus caras (también las ocultas), evitar el contacto con pisos húmedos y mantener ventilación.'),
('cuidado', 'ambos', 'Prevención del comején', 'comején termitas plaga yucatán tratamiento',
 'El comején es común en Yucatán. Ayuda elegir maderas resistentes como cedro o tzalam, aplicar tratamiento preventivo, evitar el contacto de la madera con tierra o muros húmedos y revisar periódicamente.'),
('cuidado', 'ambos', 'Sol directo', 'sol uv decoloración cortinas',
 'La luz solar decolora y reseca la madera. Usa acabados con filtro UV y protege los muebles con cortinas o persianas.'),
('cuidado', 'cliente', 'Limpieza y mantenimiento de muebles', 'limpieza mantenimiento paño posavasos',
 'Limpia con un paño seco o apenas húmedo, sin químicos abrasivos. Usa posavasos y manteles para evitar manchas de calor y agua. Los acabados con aceite o cera se reaplican cada cierto tiempo.'),
('cuidado', 'ambos', 'Muebles en cocinas y baños', 'cocina baño humedad mdf rh silicón',
 'En zonas húmedas se recomienda MDF RH o melamina sobre MDF RH, cantos bien sellados y silicón en uniones con tarjas. Cualquier fuga de agua debe repararse pronto.'),
-- Proceso
('proceso', 'ambos', '¿Quién toma las medidas?', 'medidas cita toma de medidas carpintero',
 'En CarpiApp las medidas las toma el carpintero durante la cita. Mide en varios puntos porque los muros rara vez son perfectamente rectos y usa la medida menor para evitar problemas en la instalación. Las fotos solo son referencia visual.'),
('proceso', 'ambos', '¿Qué incluye una cotización?', 'cotización costos materiales mano de obra pdf',
 'La cotización desglosa materiales, mano de obra y costos adicionales (por ejemplo herrajes, transporte o instalación), junto con las medidas tomadas en la cita. Se entrega en PDF para descargar o imprimir.'),
('proceso', 'ambos', 'Etapas de un pedido', 'etapas estado pedido fabricación entrega',
 'Solicitud → cita para medir → cotización → aceptación → fabricación (con avances) → entrega e instalación → calificación del servicio.'),
('proceso', 'ambos', 'Tiempos de fabricación', 'tiempo entrega fecha días semanas',
 'El tiempo depende del mueble, los materiales y la carga de trabajo del taller. La fecha de entrega la confirma el carpintero en la cotización o el pedido.'),
('proceso', 'carpintero', 'Cómo hacer un despiece', 'despiece corte optimización tablero 122 244',
 'Haz la lista de piezas con largo, ancho, grosor y cantidad. Acomódalas en tableros de 1.22 × 2.44 m considerando el grueso de la sierra (≈3 mm) y el tapacanto. Agrupa piezas del mismo material y color.'),
('proceso', 'carpintero', 'Estimar el costo de materiales', 'costo materiales tableros desperdicio presupuesto',
 'Número de tableros ≈ área total de piezas ÷ área útil del tablero, más 10–15 % de desperdicio. Suma herrajes, tapacanto, tornillería, pegamento y acabados.'),
('proceso', 'ambos', 'Medidas estándar de muebles', 'medidas estándar altura mesa escritorio cocina closet',
 'Referencias comunes: mesa de comedor ≈ 75 cm de alto; escritorio 73–76 cm; cubierta de cocina ≈ 90 cm; gabinete superior 30–35 cm de fondo; clóset 55–60 cm de fondo; asiento de silla ≈ 45 cm. Cada proyecto se ajusta al espacio real.'),
-- App
('app', 'cliente', 'Cómo solicitar un mueble', 'solicitar cotización pedido cita fotos',
 'Ve a "Solicitar cotización", elige la carpintería, el tipo de mueble, el material o acabado que te gusta, describe tu idea, agrega fotos de referencia y propone la fecha de la cita. No necesitas medidas: el carpintero las toma en la cita.'),
('app', 'ambos', 'Qué puede hacer el asistente', 'asistente ia ayuda límites',
 'El asistente da información general de maderas, tableros, acabados y cuidados, consulta proveedores locales y ayuda a organizar solicitudes. No diseña muebles ni confirma precios, medidas, materiales definitivos o fechas: eso lo acuerdas con el carpintero.'),
('app', 'cliente', 'Responder una cotización', 'aceptar rechazar ajustes cotización pdf',
 'En "Mis pedidos" abre el pedido y revisa la cotización en PDF. Puedes aceptarla, pedir ajustes con un comentario o rechazarla.'),
('app', 'ambos', 'Vista en realidad aumentada', 'realidad aumentada ar vista espacio 3d',
 'La vista en realidad aumentada coloca un modelo de referencia del mueble en tu espacio. Es aproximada: no representa medidas exactas ni sustituye la visita del carpintero.');
